ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS role TEXT;

UPDATE public.questions SET role = CASE sector
  WHEN 'it' THEN 'Software Engineer'
  WHEN 'software' THEN 'Software Engineer'
  WHEN 'civil-services' THEN 'Civil Services (IAS/IPS)'
  WHEN 'government' THEN 'Government Officer'
  WHEN 'banking' THEN 'Bank PO / Officer'
  WHEN 'teaching' THEN 'School Teacher'
  WHEN 'sales' THEN 'Sales Executive'
  WHEN 'healthcare' THEN 'Staff Nurse'
  ELSE 'Any role'
END WHERE role IS NULL;

